def W(phase, emoji, title, titleDe, grammar, vocab, nicos, book, lessons, videos, speak, write, listen, read, test, read_task=None, extra=None):
    return dict(phase=phase, emoji=emoji, title=title, titleDe=titleDe, grammar=grammar, vocab=vocab, nicos=nicos, book=book, lessons=lessons, videos=videos,
                speak=speak, write=write, listen=listen, read=read, test=test, readTask=read_task, extra=extra)

def RT(title, text, qs):
    return {'title': title, 'text': text, 'questions': [{'q': q, 'options': o, 'answer': a} for q, o, a in qs]}

